import { Flex } from '@docs-front/ui';
import {
  StyledModalOverlay,
  StyledProfileContainer,
  StyledSideNavigationHeader,
  StyledSideNavigationModal
} from '@/routes/_authenticated/-components/SideNavigation/SideNavigation.style';
import { FileCheck, Inbox } from 'lucide-react';
import { ProfileItem } from '@/routes/_authenticated/-components/SideNavigation/components/ProfileItem/ProfileItem';
import { DocshuntLogo2 } from '@docs-front/ui';
import { useI18n } from '@/hooks/useI18n';
import { useLocation, useNavigate } from '@tanstack/react-router';
import { useSideNavigationModalStore } from '@/store/useSideNavigationModalStore';
import { useBreakPoints } from '@/hooks/useBreakPoints';
import { FilePlusCorner } from '@docs-front/ui';
import { NavIcon } from '@/routes/_authenticated/-components/SideNavigation/components/deprecated/NavItem/NavItem';

export default function SideNavigationModal() {
  const { t } = useI18n(['main']);
  const navigate = useNavigate();
  const { close } = useSideNavigationModalStore();
  const { sm } = useBreakPoints();
  const location = useLocation();

  const handleNavigate = (to: string) => {
    navigate({ to });
  };

  const handleClose = () => {
    close();
  };

  return (
    <>
      <StyledModalOverlay onClick={handleClose} />
      <StyledSideNavigationModal sm={sm}>
        <StyledSideNavigationHeader>
          <Flex
            alignItems="center"
            justify="space-between"
            width="100%"
            padding={'10px 12px'}
          >
            <DocshuntLogo2 />
          </Flex>
          <Flex direction="column" width="100%" gap={10}>
            <NavIcon
              label={t('mainPage.sideNavigation.create')}
              icon={<FilePlusCorner />}
              open={true}
              onClick={() => handleNavigate('/start')}
              isActive={
                location.pathname === '/start' ||
                location.pathname.startsWith('/start/')
              }
            />
            <NavIcon
              label={t('mainPage.sideNavigation.fill')}
              icon={<FileCheck size={20} strokeWidth={1.6} />}
              open={true}
              onClick={() => handleNavigate('/f/template')}
              isActive={
                location.pathname.startsWith('/f/')
              }
            />
            <NavIcon
              label={t('mainPage.sideNavigation.docs')}
              icon={<Inbox size={20} strokeWidth={1.6} />}
              open={true}
              onClick={() => handleNavigate('/d')}
              isActive={
                location.pathname === '/d' ||
                location.pathname.startsWith('/d/')
              }
            />
          </Flex>
        </StyledSideNavigationHeader>
        {/*UX 개선에 따라 제거 예정*/}
        {/* <StyledScrollableContainer>
          <Flex padding="0 8px">
            <StyledSideNavigationDivider />
          </Flex>
          <Flex alignItems="start" padding="4px 12px">
            <StyledHeading2>
              {t('mainPage.sideNavigation.record')}
            </StyledHeading2>
          </Flex>
          <Suspense>
            <NavItemList />
          </Suspense>
        </StyledScrollableContainer> */}
        <StyledProfileContainer>
          <ProfileItem open={true} />
        </StyledProfileContainer>
      </StyledSideNavigationModal>
    </>
  );
}
